package org.jfree.data.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;

public class Week_Week_TriageGen0Test {













    @Test
    public void testMillisecondBounds() {
        Calendar cal = Calendar.getInstance();
        cal.set(2023, Calendar.JUNE, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        Week week = new Week(date);

        long first = week.getFirstMillisecond();
        long last = week.getLastMillisecond();

        assertNotNull(week);
        // A week is 7 days. 7 * 24 * 60 * 60 * 1000 = 604800000
        assertEquals(604800000L, last - first + 1); 
    }








}

